{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Glitch in the System",
          "intent": "Introduce the protagonist and establish the logic error in the tutorial's combat math.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist confirms the specific sequence of actions required to trigger the infinite crit multiplier."
        },
        {
          "section_id": 2,
          "title": "Tutorial Speedrun",
          "intent": "Demonstrate the protagonist's skill at exploiting the system while navigating the tutorial dungeon.",
          "section_role": "build-up",
          "target_scene_count": 4,
          "end_condition": "The protagonist reaches the threshold of the final tutorial arena where the scripted boss awaits."
        },
        {
          "section_id": 3,
          "title": "Breaking the Script",
          "intent": "Execute the exploit to kill the invincible boss and exit the tutorial with illegal stats.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The tutorial boss is defeated and the protagonist is forcibly spawned into the main world map."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Illegal Grind",
          "intent": "Show the protagonist power-leveling on high-tier mobs using his glass-cannon build.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "A high-tier mob spawn point is located and successfully farmed for massive XP."
        },
        {
          "section_id": 2,
          "title": "Cross-Country Sprint",
          "intent": "The protagonist travels toward Oakhaven while evading low-level players and aggressive wildlife.",
          "section_role": "build-up",
          "target_scene_count": 3,
          "end_condition": "The protagonist arrives at the main gates of the hub city, Oakhaven."
        },
        {
          "section_id": 3,
          "title": "Leaderboard Shock",
          "intent": "The protagonist's presence is felt through the global system notifications.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The protagonist confirms his position at the top of the world clear-time leaderboards."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Under the Radar",
          "intent": "The protagonist attempts to blend into Oakhaven while the Sentinels begin their search.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist narrowly avoids a direct confrontation with a Sentinel patrol."
        },
        {
          "section_id": 2,
          "title": "Urban Exploits",
          "intent": "The protagonist uses city geometry and logic gaps to evade pursuit through the streets.",
          "section_role": "build-up",
          "target_scene_count": 4,
          "end_condition": "The protagonist successfully loses his tail by exploiting a glitched alleyway boundary."
        },
        {
          "section_id": 3,
          "title": "The Slum Sanctuary",
          "intent": "Establish a hidden base of operations and gather intel on the Sentinels.",
          "section_role": "resolution",
          "target_scene_count": 3,
          "end_condition": "A temporary safe house is secured and the protagonist prepares his next move."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Nerf Hammer",
          "intent": "The system issues a hotfix that disables the protagonist's primary crit exploit.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "The protagonist's primary skill fails to trigger during a routine encounter, confirming the nerf."
        },
        {
          "section_id": 2,
          "title": "Searching for a Workaround",
          "intent": "The protagonist hunts for rumors of 'Logic Breaker' items to regain his edge.",
          "section_role": "build-up",
          "target_scene_count": 4,
          "end_condition": "The location and coordinates of the Logic Breaker artifact are successfully decrypted."
        },
        {
          "section_id": 3,
          "title": "The Heist Plan",
          "intent": "The protagonist prepares for a high-risk infiltration of the Vault of Eternal Invariants.",
          "section_role": "preparation",
          "target_scene_count": 4,
          "end_condition": "The protagonist departs for the Vault, knowing he has no room for error."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Infiltration",
          "intent": "Navigate the outer defenses and traps of the Vault.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist breaches the inner sanctum of the Vault."
        },
        {
          "section_id": 2,
          "title": "The Invariant Puzzles",
          "intent": "Solve mechanical puzzles designed to stop anyone not thinking outside the box.",
          "section_role": "build-up",
          "target_scene_count": 3,
          "end_condition": "The protagonist reaches the central pedestal holding the Logic Breaker artifact."
        },
        {
          "section_id": 3,
          "title": "Lockdown",
          "intent": "The Sentinels arrive and seal the Vault, trapping the protagonist inside.",
          "section_role": "pressure",
          "target_scene_count": 3,
          "end_condition": "The Vault's main doors are locked from the outside by Sentinel forces."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Guardian's Wake",
          "intent": "The final defense of the Vault activates to protect the artifact.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The Vault Guardian's health bar appears and the boss arena is sealed."
        },
        {
          "section_id": 2,
          "title": "Frame-Perfect Combat",
          "intent": "The protagonist uses the new artifact to discover a frame-perfect exploit to damage the boss.",
          "section_role": "climax",
          "target_scene_count": 5,
          "end_condition": "The Vault Guardian is shattered by a single, massive critical hit."
        },
        {
          "section_id": 3,
          "title": "The Collapse",
          "intent": "The Vault begins to self-destruct as the protagonist grabs the loot.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "The artifact is secured and the structural integrity of the Vault fails."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Great Escape",
          "intent": "The protagonist flees the collapsing ruins while dodging the remaining Sentinels.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The protagonist emerges from the dust of the collapsed Vault and evades the initial perimeter."
        },
        {
          "section_id": 2,
          "title": "Crossing the Border",
          "intent": "The protagonist makes a break for the unexplored frontier where the System's reach is weak.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The protagonist crosses the invisible boundary into the lawless frontier."
        },
        {
          "section_id": 3,
          "title": "The New Legend",
          "intent": "Establish the protagonist's new status as a global threat and rebel icon.",
          "section_role": "aftermath",
          "target_scene_count": 2,
          "end_condition": "The protagonist views the global 'Wanted' broadcast and prepares for his next exploit."
        }
      ]
    }
  ]
}

