        "expected_scene_count": 10,
        "intensity": 4,
        "tempo": "rush"
      },
      "stakes_shift": "From certain death to becoming a lethal glass cannon with a target on his back.",
      "title": "Default Settings are for Losers"
    },
    {
      "bridge": {
        "from_prev": "Enters the main world map with an illegal stat spread and zero defense.",
        "to_next": "Local authorities flag the protagonist's impossible clear times, initiating a silent hunt."
