      "chapter_role": "setup",
      "goal": "Reach the hub city of Oakhaven while power-leveling on high-tier mobs that should be impossible to kill.",
      "pacing": {
        "expected_scene_count": 8,
        "intensity": 2,
        "tempo": "steady"
      },
      "stakes_shift": "From a lucky survivor to an infamous 'glitcher' whose clear times are breaking the leaderboards.",
      "title": "The RNG Whisperer"
    },
    {
      "bridge": {
        "from_prev": "Local authorities flag the protagonist's impossible clear times, initiating a silent hunt.",
        "to_next": "Forced into a corner, the protagonist attempts a high-risk exploit that triggers a mid-day system patch."
      },
      "chapter_id": 3,
      "chapter_role": "pressure",
      "goal": "Evade the 'System Sentinels'\u2014a guild of enforcers\u2014by utilizing environmental exploits and social engineering.",
      "pacing": {
