        "intensity": 3,
        "tempo": "steady"
      },
      "stakes_shift": "From a simple power-leveling run to a desperate game of cat-and-mouse where capture means a character wipe.",
      "title": "Aggro Management"
    },
    {
      "bridge": {
        "from_prev": "Forced into a corner, the protagonist attempts a high-risk exploit that triggers a mid-day system patch.",
        "to_next": "Deprived of his main exploit, he must infiltrate a high-security vault to find a more permanent 'Logic Breaker'."
      },
      "chapter_id": 4,
      "chapter_role": "reversal",
      "goal": "Adapt to the System's hotfix which nerfs his primary exploit, requiring him to find a 'Logic Breaker' artifact to stay relevant.",
      "pacing": {
        "expected_scene_count": 12,
        "intensity": 4,
        "tempo": "rush"
      },
      "stakes_shift": "From an overpowered exploiter to a vulnerable target who must now play by the rules\u2014or find better ones.",
      "title": "Patch Notes from Hell"
    },
    {
      "bridge": {
        "from_prev": "Deprived of his main exploit, he must infiltrate a high-security vault to find a more permanent 'Logic Breaker'.",
        "to_next": "Reaches the heart of the vault where the guardian and the ultimate loot await."
      },
      "chapter_id": 5,
      "chapter_role": "trial",
      "goal": "Infiltrate the Vault of Eternal Invariants to steal the artifact before the Sentinels lock down the zone.",
      "pacing": {
        "expected_scene_count": 9,
        "intensity": 3,
        "tempo": "steady"
      },
      "stakes_shift": "From reactive survival to an intentional disruption of the world's power balance.",
      "title": "The Glass Cannon Run"
    },
    {
      "bridge": {
        "from_prev": "Reaches the heart of the vault where the guardian and the ultimate loot await.",
        "to_next": "The vault collapses as the protagonist makes a desperate run for the exit with the artifact."
      },
      "chapter_id": 6,
      "chapter_role": "climax",
      "goal": "Defeat the Vault Guardian by combining the new artifact with a frame-perfect exploit, proving the system is still his plaything.",
      "pacing": {
        "expected_scene_count": 11,
        "intensity": 5,
        "tempo": "rush"
      },
      "stakes_shift": "From a hunted criminal to a recognized threat capable of destabilizing the entire game economy.",
      "title": "Maximum Over-Crit"
    },
    {
      "bridge": {
        "from_prev": "The vault collapses as the protagonist makes a desperate run for the exit with the artifact.",
        "to_next": "Disappears into the unexplored wilds, ready to break the next set of rules."
      },
      "chapter_id": 7,
      "chapter_role": "aftermath",
      "goal": "Escape the collapsing zone and vanish into the frontier, setting the stage for a larger rebellion against the System.",
      "pacing": {
        "expected_scene_count": 7,
        "intensity": 2,
        "tempo": "steady"
      },
      "stakes_shift": "From a lone exploiter to a symbol of mechanical rebellion, with the entire world now looking for the 'Crit King'.",
      "title": "Loot, Scoot, and Reboot"
    }
  ],
  "schema_version": "spine_v1"
}

